"""BR-C1 independent specification; no planner imports, effects or source discovery."""
import json,hashlib

def canon(x):return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode('utf-8')
def digest(x):return hashlib.sha256(canon(x)).hexdigest()
def ptr(x,p):
 for part in p.split('/')[1:]:
  part=part.replace('~1','/').replace('~0','~');x=x[int(part)] if isinstance(x,list) else x[part]
 return x
def parse(text):
 def pairs(xs):
  d={}
  for k,v in xs:
   if k in d:raise ValueError('DUPLICATE_KEY')
   d[k]=v
  return d
 return json.loads(text,object_pairs_hook=pairs)
def need(ok,clause):
 if not ok:raise ValueError(clause)
def material(contract,records,validity):
 need(type(records)is list,'SOURCE_SCHEMA');ids=[r['role'] for r in records];need(len(ids)==len(set(ids)),'AMBIGUOUS_CORRESPONDENCE')
 need(set(ids)==set(contract['sources']),'MALFORMED_MISSING_SOURCE')
 need(set(validity)==set(ids),'VALIDITY_INVENTORY');raw={};docs={}
 for r in records:
  e=contract['sources'][r['role']];need(r['identity']==e['identity'],'SOURCE_IDENTITY_DOMAIN')
  need(hashlib.sha256(r['text'].encode()).hexdigest()==e['identity']['sha256'],'SUBSTITUTED_SOURCE')
  need(validity[r['role']]=={'identity':e['identity'],'state':'CURRENT_AT_PINNED_SNAPSHOT'},'STALE_PRESENT_SOURCE')
  raw[r['role']]=r['text']
  if e['encoding']=='JSON':docs[r['role']]=parse(r['text'])
 return raw,docs

def project(contract,records,validity):
 try:
  raw,d=material(contract,records,validity);out=[]
  for b in contract['present']:
   if b['transform']=='RAW_CONTENT_IDENTITY':value={'domain':'CONTENT_IDENTITY','sha256':hashlib.sha256(raw[b['role']].encode()).hexdigest()}
   elif b['transform']=='EXTRACTED_JSON_IDENTITY':value={'domain':'CONTENT_IDENTITY','namespace':'EXTRACTED_JSON_VALUE','sha256':digest(ptr(d[b['role']],b['selector']))}
   elif b['transform']=='TAGGED_SUBJECT_REFERENCE':value={'domain':b['target']['domain'],'value':ptr(d[b['role']],b['selector'])}
   else:raise ValueError('UNSUPPORTED_SOURCE')
   # A descriptor states the join, but the source must independently carry the expected identity.
   if b.get('join'):
    j=b['join'];jval=ptr(d[j['role']],j['selector']);need(jval==value['sha256'],'WRONG_JOIN_TARGET')
   out.append({'id':b['id'],'state':'KNOWN_PRESENT','binding_kind':'PRESENT_BINDING','source_identity':contract['sources'][b['role']]['identity'],'target_identity':value,'context':contract['context'],'provenance':b['provenance'],'dependencies':b['dependencies'],'validity':'CURRENT_AT_PINNED_SNAPSHOT','positive_subject_applicability':False})
  m=d['manifest'];h=d['handoff'];absences=[]
  for rule in contract['absences']:
   routes=[x for x in m['request_routes'] if x['request_id']==rule['request_id']];bundles=[x for x in h['external_request_bundles'] if x['request_id']==rule['request_id']]
   need(len(routes)==len(bundles)==1,'AMBIGUOUS_ROUTE');r=routes[0];b=bundles[0]
   need(r['evidence_received'] is False and r['state']=='WAITING_FOR_EXTERNAL_INPUT','ABSENCE_NOT_ESTABLISHED')
   need(r['handoff_ids']==b['handoff_ids']==rule['handoff_ids'],'GATE_JOIN')
   need(r['receipt_action']==b['receipt']['id']==rule['receipt_action'] and r['reentry_actions']==b['receipt']['reentry']==rule['reentry_actions'],'RECEIPT_REENTRY_ROUTE')
   items=[x for x in h['control_transfer_items'] if x['id'] in r['handoff_ids']];need(len(items)==len(r['handoff_ids']),'MISSING_EXTERNAL_GATE')
   need([{k:x[k] for k in ['id','frontier_member','exact_missing_propositions','expected_owner','acceptable_evidence_source','scope_lineage_requirements','freshness_currentness_requirements']} for x in items]==rule['requirements'],'WRONG_MISSING_PROPOSITION')
   absences.append({'request_id':r['request_id'],'state':'KNOWN_ABSENT','absence_kind':'EXPECTED_EXTERNAL_ABSENCE','gate_state':'WAITING_FOR_EXTERNAL_EVIDENCE','evidence':None,'requirements':rule['requirements'],'receipt_action':r['receipt_action'],'reentry_actions':r['reentry_actions'],'context':contract['context'],'provenance':rule['provenance'],'dependencies':rule['dependencies'],'positive_reentry':False})
  return {'accepted':True,'state':{'schema':'BR-C1-RESTORED-BINDINGS-1','contract_pin':digest(contract),'mode':'SYNTHETIC_QUALIFICATION_ONLY','present':sorted(out,key=lambda x:x['id']),'absences':sorted(absences,key=lambda x:x['request_id']),'resume_allowed':False,'newly_runnable':[]},'failed_clause':None}
 except (KeyError,IndexError,TypeError,ValueError) as e:return {'accepted':False,'state':None,'failed_clause':str(e)}

def admit(contract,candidate,records,validity):
 """Independent target checks: expected targets come from the pinned contract, not project()."""
 try:
  material(contract,records,validity)
  need(set(candidate)=={'schema','contract_pin','mode','present','absences','resume_allowed','newly_runnable'},'STATE_SCHEMA')
  need(candidate['schema']=='BR-C1-RESTORED-BINDINGS-1' and candidate['contract_pin']==digest(contract) and candidate['mode']=='SYNTHETIC_QUALIFICATION_ONLY','TRUSTED_CONTRACT_BINDING')
  rows={x['id']:x for x in candidate['present']};need(len(rows)==len(candidate['present']) and set(rows)=={x['id'] for x in contract['present']},'PRESENT_INVENTORY')
  for b in contract['present']:
   a=rows[b['id']];need(set(a)=={'id','state','binding_kind','source_identity','target_identity','context','provenance','dependencies','validity','positive_subject_applicability'},'BINDING_SCHEMA')
   need(a['state']=='KNOWN_PRESENT' and a['binding_kind']=='PRESENT_BINDING','PRESENT_STATE')
   need(a['source_identity']==contract['sources'][b['role']]['identity'] and a['target_identity']==b['target'],'TARGET_IDENTITY_DOMAIN')
   need(a['context']==contract['context'],'ENVELOPE_SCOPE_LINEAGE');need(a['provenance']==b['provenance'] and a['dependencies']==b['dependencies'],'PROVENANCE_DEPENDENCIES')
   need(a['validity']=='CURRENT_AT_PINNED_SNAPSHOT' and a['positive_subject_applicability'] is False,'CURRENTNESS_NOT_APPLICABILITY')
  ar={x['request_id']:x for x in candidate['absences']};need(len(ar)==len(candidate['absences']) and set(ar)=={x['request_id'] for x in contract['absences']},'ABSENCE_INVENTORY')
  for r in contract['absences']:
   a=ar[r['request_id']];need(set(a)=={'request_id','state','absence_kind','gate_state','evidence','requirements','receipt_action','reentry_actions','context','provenance','dependencies','positive_reentry'},'ABSENCE_SCHEMA')
   need(a['state']=='KNOWN_ABSENT' and a['absence_kind']=='EXPECTED_EXTERNAL_ABSENCE' and a['gate_state']=='WAITING_FOR_EXTERNAL_EVIDENCE' and a['evidence'] is None,'ABSENCE_GATE_STATE')
   for k in ['requirements','receipt_action','reentry_actions','provenance','dependencies']:need(a[k]==r[k],'ABSENCE_'+k.upper())
   need(a['context']==contract['context'],'ENVELOPE_SCOPE_LINEAGE');need(a['positive_reentry'] is False,'NO_POSITIVE_REENTRY')
  need(candidate['resume_allowed'] is False and candidate['newly_runnable']==[],'NO_RESUME_OR_RUNNABLE')
  return {'accepted':True,'failed_clause':None}
 except (KeyError,TypeError,ValueError) as e:return {'accepted':False,'failed_clause':str(e)}
